#include <iostream>
#include <string>

#include <boost/program_options.hpp>

#include "server.h"

namespace po = boost::program_options;

int main(int argc, char* argv[]) {
  std::string host;
  int port = 0;
  bool verbose = false;

  po::options_description desc("Options");
  desc.add_options()
      ("help,h", "show this help")
      ("host", po::value<std::string>(&host)->default_value("127.0.0.1"), "address to bind")
      ("port,p", po::value<int>(&port)->default_value(8080), "port to listen on")
      ("verbose,v", po::bool_switch(&verbose), "log every request");

  po::variables_map vm;
  try {
    po::store(po::parse_command_line(argc, argv, desc), vm);
    if (vm.count("help")) {
      std::cout << desc << "\n";
      return 0;
    }
    po::notify(vm);
  } catch (const po::error& e) {
    std::cerr << e.what() << "\n" << desc << "\n";
    return 1;
  }

  return run_server(host, port, verbose);
}
